return items.filter(item => {
  const domain = item.json.domain;
  const attendees = item.json.meeting_attendees || [];

  if (domain) {
    return attendees.some(p => p.email && p.email.endsWith("@" + domain));
  }

  return true; 
});

const notes = items[0].json.notes || [];
let combined = `Below are the summaries and notes from multiple sales meetings. Generate a combined Handoff Report with the following sections:
Sales Conversations:
- Their Goals
- Biggest Problems
- What we said we'd do
- What they want from us
- What was discussed
Moving Forward:
- Key talking points
- Unclosed Loops from the Sales Process
---\n\n`;

notes.forEach((note, i) => {
  // Extract title from the body (look for "Title:" pattern with or without emoji)
  const titleMatch = note.body.match(/(?:📞\s*)?Title:\s*(.+)/i);
  const title = titleMatch ? titleMatch[1].trim() : `Meeting ${i + 1}`;

  // Extract date from the body (look for "Date:" pattern with or without emoji)
  const dateMatch = note.body.match(/(?:📅\s*)?Date:\s*(.+)/i);
  const date = dateMatch ? dateMatch[1].trim() : '';

  // Extract summary from the body (look for "Summary:" section with or without emoji)
  const summaryMatch = note.body.match(/(?:✏️\s*)?Summary:\s*([\s\S]*?)(?=(?:📝|🔗|\*\*|Action Items:|Recording URL:|Transcript URL:|$))/i);
  const summary = summaryMatch ? summaryMatch[1].trim() : "No summary available.";

  // Extract action items from the body (look for "Action Items:" section with or without emoji)
  const actionMatch = note.body.match(/(?:📝\s*)?Action Items:\s*([\s\S]*?)(?=🔗|Recording URL:|Transcript URL:|$)/i);
  const actions = actionMatch ? actionMatch[1].trim() : "No action items available.";

  combined += `📝 Meeting Title: ${title}\n`;
  if (date) {
    combined += `📅 Date: ${date}\n`;
  }
  combined += `📋 Summary:\n${summary}\n`;
  combined += `✅ Action Items:\n${actions}\n`;
  combined += `---\n\n`;
});

return [
  {
    json: {
      full_transcript_text: combined
    }
  }
];

