// OPTION 1: Function Node for HTTP Request to Google Docs API
// This creates the proper API request structure

// Function to convert Markdown to Google Docs API requests
function convertMarkdownToGoogleDocsRequests(markdownText, insertIndex = 1) {
  const requests = [];
  const lines = markdownText.split('\n');
  let currentIndex = insertIndex;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();

    if (line === '') {
      requests.push({
        insertText: {
          location: { index: currentIndex },
          text: '\n'
        }
      });
      currentIndex += 1;
      continue;
    }

    // Check for headings
    if (line.startsWith('#')) {
      const headingMatch = line.match(/^(#{1,6})\s+(.+)$/);
      if (headingMatch) {
        const headingLevel = headingMatch[1].length;
        const headingText = headingMatch[2];
        const headingStyle = `HEADING_${headingLevel}`;

        requests.push({
          insertText: {
            location: { index: currentIndex },
            text: headingText + '\n'
          }
        });

        requests.push({
          updateParagraphStyle: {
            range: {
              startIndex: currentIndex,
              endIndex: currentIndex + headingText.length
            },
            paragraphStyle: {
              namedStyleType: headingStyle
            },
            fields: 'namedStyleType'
          }
        });

        currentIndex += headingText.length + 1;
        continue;
      }
    }

    // Check for bullet points
    if (line.startsWith('- ') || line.startsWith('* ')) {
      const bulletText = line.substring(2);

      requests.push({
        insertText: {
          location: { index: currentIndex },
          text: bulletText + '\n'
        }
      });

      requests.push({
        createParagraphBullets: {
          range: {
            startIndex: currentIndex,
            endIndex: currentIndex + bulletText.length
          },
          bulletPreset: 'BULLET_DISC_CIRCLE_SQUARE'
        }
      });

      currentIndex += bulletText.length + 1;
      continue;
    }

    // Check for numbered lists
    if (line.match(/^\d+\.\s/)) {
      const numberedText = line.replace(/^\d+\.\s/, '');

      requests.push({
        insertText: {
          location: { index: currentIndex },
          text: numberedText + '\n'
        }
      });

      requests.push({
        createParagraphBullets: {
          range: {
            startIndex: currentIndex,
            endIndex: currentIndex + numberedText.length
          },
          bulletPreset: 'NUMBERED_DECIMAL_ALPHA_ROMAN'
        }
      });

      currentIndex += numberedText.length + 1;
      continue;
    }

    // Process regular text with inline formatting
    const processedLine = processInlineFormatting(line, currentIndex);

    requests.push({
      insertText: {
        location: { index: currentIndex },
        text: processedLine.text + '\n'
      }
    });

    requests.push(...processedLine.formatRequests);
    currentIndex += processedLine.text.length + 1;
  }

  return requests;
}

function processInlineFormatting(text, startIndex) {
  let processedText = text;
  const formatRequests = [];
  let offset = 0;

  // Process bold text
  const boldMatches = [...text.matchAll(/(\*\*|__)(.*?)\1/g)];
  for (const match of boldMatches) {
    const matchStart = match.index - offset;
    const matchLength = match[2].length;
    const actualStart = startIndex + matchStart;

    processedText = processedText.replace(match[0], match[2]);
    offset += match[1].length * 2;

    formatRequests.push({
      updateTextStyle: {
        range: {
          startIndex: actualStart,
          endIndex: actualStart + matchLength
        },
        textStyle: { bold: true },
        fields: 'bold'
      }
    });
  }

  // Process italic text
  const italicMatches = [...processedText.matchAll(/(?<!\*)(\*|_)(?!\*)([^*_]+?)(?<!\*)\1(?!\*)/g)];
  for (const match of italicMatches) {
    const matchStart = match.index;
    const matchLength = match[2].length;
    const actualStart = startIndex + matchStart;

    formatRequests.push({
      updateTextStyle: {
        range: {
          startIndex: actualStart,
          endIndex: actualStart + matchLength
        },
        textStyle: { italic: true },
        fields: 'italic'
      }
    });

    processedText = processedText.replace(match[0], match[2]);
  }

  return { text: processedText, formatRequests };
}

